//! Markdown rule reference generation (TRD §8.2: documentation generated from the same source
//! the engine is built from, so it cannot drift from behavior).

use std::fmt::Write as _;

use crate::{Compiled, Detector, Rule};

pub fn generate_markdown(c: &Compiled) -> String {
    let mut s = String::new();
    let w = &mut s;
    // `fmt::Write` for `String` never fails; results are discarded deliberately.
    let _ = writeln!(
        w,
        "<!-- @generated by `cargo run -p spymonk-redact-rules --bin gen-docs` from rules/rules.v1.json. Do not edit. -->"
    );
    let _ = writeln!(w);
    let _ = writeln!(w, "# SpyMonk Redact rule reference");
    let _ = writeln!(w);
    let _ = writeln!(w, "| Field | Value |");
    let _ = writeln!(w, "| --- | --- |");
    let _ = writeln!(w, "| Rule-set version | `{}` |", c.rule_version);
    let _ = writeln!(w, "| Rule-set SHA-256 | `{}` |", c.sha256_hex);
    let _ = writeln!(w, "| Manifest schema | `{}` |", c.schema_version);
    let _ = writeln!(w);
    let _ = writeln!(
        w,
        "Every binary reports this hash in `spymonk-redact --version`, so you can confirm which rules produced an output. Detection is limited to the grammars below: review every output before sharing, and rotate any credential that was already exposed."
    );
    let _ = writeln!(w);
    let _ = writeln!(w, "## Summary");
    let _ = writeln!(w);
    let _ = writeln!(w, "| ID | Rule | Enabled | Placeholder |");
    let _ = writeln!(w, "| --- | --- | --- | --- |");
    for r in &c.rules {
        let enabled = match (r.optional, r.default_enabled) {
            (false, _) => "Always",
            (true, true) => "Default on",
            (true, false) => "Default off",
        };
        let _ = writeln!(
            w,
            "| {} | {} | {} | `{}` |",
            r.id,
            cell(&r.name),
            enabled,
            r.placeholder
        );
    }
    let _ = writeln!(w);
    let _ = writeln!(
        w,
        "When candidates from different rules cover the identical range, the highest-precedence rule wins. When they overlap with different ranges, their union is replaced (by their shared placeholder, otherwise `[REDACTED]`) and counted once. Precedence, highest first: {}.",
        c.precedence.join(", ")
    );
    let _ = writeln!(w);
    let _ = writeln!(
        w,
        "Reserved placeholders: {}. A value that is exactly a placeholder is never redacted again.",
        c.placeholders
            .iter()
            .map(|p| format!("`{p}`"))
            .collect::<Vec<_>>()
            .join(", ")
    );

    for r in &c.rules {
        rule_section(w, r);
    }
    s
}

fn rule_section(w: &mut String, r: &Rule) {
    let _ = writeln!(w);
    let _ = writeln!(w, "## {}: {}", r.id, r.name);
    let _ = writeln!(w);
    let _ = writeln!(w, "{}", r.description);
    let _ = writeln!(w);
    if !r.examples.is_empty() {
        let _ = writeln!(w, "| Input | Output |");
        let _ = writeln!(w, "| --- | --- |");
        for (input, output) in &r.examples {
            let _ = writeln!(w, "| {} | {} |", code(input), code(output));
        }
        let _ = writeln!(w);
    }
    if !r.non_examples.is_empty() {
        let items: Vec<String> = r.non_examples.iter().map(|n| code(n)).collect();
        let _ = writeln!(w, "Not matched by this rule: {}.", items.join(", "));
        let _ = writeln!(w);
    }
    let d = &r.data;
    match r.detector {
        Detector::NamedValue => {
            let _ = writeln!(
                w,
                "Final-segment aliases: {}.",
                inline_list(&d.single_aliases)
            );
            let _ = writeln!(w);
            let pairs: Vec<String> = d
                .pair_aliases
                .iter()
                .map(|(a, b)| format!("{a} {b}"))
                .collect();
            let _ = writeln!(w, "Final-two-segment aliases: {}.", inline_list(&pairs));
            let _ = writeln!(w);
            let _ = writeln!(
                w,
                "Unquoted values left unchanged: {}.",
                inline_list(&d.skip_values)
            );
            let _ = writeln!(w);
        }
        Detector::Authorization => {
            let _ = writeln!(
                w,
                "Field names (case-insensitive): {}.",
                inline_list(&d.headers)
            );
            let _ = writeln!(w);
            let _ = writeln!(
                w,
                "Recognized schemes (case-insensitive): {}.",
                inline_list(&d.schemes)
            );
            let _ = writeln!(w);
        }
        Detector::Cookie => {
            let _ = writeln!(
                w,
                "Request fields: {}. Response fields: {}.",
                inline_list(&d.request_headers),
                inline_list(&d.response_headers)
            );
            let _ = writeln!(w);
        }
        Detector::HomePath => {
            let _ = writeln!(
                w,
                "POSIX prefixes: {}. Windows: a drive letter, then `{}` (case-insensitive).",
                inline_list(&d.posix_prefixes),
                d.windows_directory
            );
            let _ = writeln!(w);
        }
        Detector::PrivateIp => {
            let mut ranges: Vec<String> = d
                .ipv4
                .iter()
                .map(|(net, len)| format!("{}/{len}", std::net::Ipv4Addr::from(*net)))
                .collect();
            ranges.extend(
                d.ipv6
                    .iter()
                    .map(|(net, len)| format!("{}/{len}", std::net::Ipv6Addr::from(*net))),
            );
            let _ = writeln!(w, "Ranges: {}.", inline_list(&ranges));
            let _ = writeln!(w);
        }
        Detector::TokenFormat => {
            let _ = writeln!(w, "| Format | Provider | Grammar | Source |");
            let _ = writeln!(w, "| --- | --- | --- | --- |");
            for f in &d.formats {
                let prefixes: Vec<String> = f.prefixes.iter().map(|p| format!("`{p}`")).collect();
                let segs: Vec<String> = f
                    .segments
                    .iter()
                    .map(|sg| {
                        let len = if sg.exact {
                            format!("exactly {}", sg.min)
                        } else {
                            format!("{}+", sg.min)
                        };
                        format!("{} × {}", len, sg.charset.describe())
                    })
                    .collect();
                let _ = writeln!(
                    w,
                    "| `{}` | {} | {} then {} | <{}> |",
                    f.id,
                    cell(&f.provider),
                    prefixes.join(" or "),
                    cell(&segs.join(" `.` ")),
                    f.source
                );
            }
            let _ = writeln!(w);
        }
        Detector::PemBlock => {
            let _ = writeln!(
                w,
                "Armor labels: up to {} characters of `[A-Z0-9 ]` followed by {}.",
                d.max_label_prefix,
                inline_list(&d.label_suffixes)
            );
            let _ = writeln!(w);
        }
        Detector::UrlCredential | Detector::Email => {}
    }
    if !r.limitations.is_empty() {
        let _ = writeln!(w, "Limitations:");
        let _ = writeln!(w);
        for l in &r.limitations {
            let _ = writeln!(w, "- {l}");
        }
    }
}

fn inline_list(items: &[String]) -> String {
    items
        .iter()
        .map(|i| format!("`{i}`"))
        .collect::<Vec<_>>()
        .join(", ")
}

/// A table-safe code span. Pipes are escaped; the content never contains backticks.
fn code(s: &str) -> String {
    format!("`{}`", s.replace('|', "\\|"))
}

fn cell(s: &str) -> String {
    s.replace('|', "\\|")
}
